    if (busy.current) return;
    busy.current = true;
    mutation.reset();
    mutation
      .mutateAsync(vars)
      .catch(() => {
        /* a refusal shows through the mutation's own error state */
      })
      .finally(() => {
        busy.current = false;
      });
